+import 'package:flutter/material.dart';
+import 'package:table_calendar/table_calendar.dart';
+import 'package:intl/intl.dart';
+import 'package:intl/date_symbol_data_local.dart';
+import 'package:cached_network_image/cached_network_image.dart';
+import 'package:shared_preferences/shared_preferences.dart';
+import 'package:url_launcher/url_launcher.dart';
+import 'models/anime_release.dart';
+import 'services/crunchyroll_service.dart';
+
+void main() async {
+  WidgetsFlutterBinding.ensureInitialized();
+  await initializeDateFormatting('de_DE', null);
+  Intl.defaultLocale = 'de_DE';
+  runApp(const MainApp());
+}
+
+class MainApp extends StatelessWidget {
+  const MainApp({super.key});
+
+  @override
+  Widget build(BuildContext context) {
+    return MaterialApp(
+      title: 'Crunchyroll Anime Kalender',
+      theme: ThemeData(
+        colorScheme: ColorScheme.fromSeed(
+          seedColor: Colors.orange,
+          brightness: Brightness.light,
+        ),
+        useMaterial3: true,
+      ),
+      darkTheme: ThemeData(
+        colorScheme: ColorScheme.fromSeed(
+          seedColor: Colors.orange,
+          brightness: Brightness.dark,
+        ),
+        useMaterial3: true,
+      ),
+      home: const CalendarPage(),
+    );
+  }
+}
+
+class CalendarPage extends StatefulWidget {
+  const CalendarPage({super.key});
+
+  @override
+  State<CalendarPage> createState() => _CalendarPageState();
+}
+
+class _CalendarPageState extends State<CalendarPage> {
+  CalendarFormat _calendarFormat = CalendarFormat.month;
+  DateTime _focusedDay = DateTime.now();
+  DateTime? _selectedDay;
+  Map<DateTime, List<AnimeRelease>> _releases = {};
+  final CrunchyrollService _crunchyrollService = CrunchyrollService();
+  bool _isLoading = false;
+  bool _isLoadingImages = false;
+  int _imagesLoaded = 0;
+  int _imagesToLoad = 0;
+
+  @override
+  void initState() {
+    super.initState();
+    _selectedDay = _focusedDay;
+    _loadCalendarFormat();
+    
+    // Registriere Callback für Bilder-Ladestatus
+    _crunchyrollService.onImageLoadingChanged = (isLoading, loaded, total) {
+      if (mounted) {
+        setState(() {
+          _isLoadingImages = isLoading;
+          _imagesLoaded = loaded;
+          _imagesToLoad = total;
+        });
+      }
+    };
+    
+    _loadReleases();
+    
+    // Starte automatische Updates alle 5 Minuten
+    _crunchyrollService.startAutoUpdate(() {
+      if (mounted) {
+        _loadReleases();
+      }
+    });
+  }
+  
+  @override
+  void dispose() {
+    _crunchyrollService.stopAutoUpdate();
+    super.dispose();
+  }
+  
+  Future<void> _loadCalendarFormat() async {
+    final prefs = await SharedPreferences.getInstance();
+    final formatIndex = prefs.getInt('calendar_format') ?? 0;
+    setState(() {
+      _calendarFormat = CalendarFormat.values[formatIndex];
+    });
+  }
+  
+  Future<void> _saveCalendarFormat(CalendarFormat format) async {
+    final prefs = await SharedPreferences.getInstance();
+    await prefs.setInt('calendar_format', format.index);
+  }
+
+  Future<void> _loadReleases() async {
+    setState(() {
+      _isLoading = true;
+    });
+
+    try {
+      final releases = await _crunchyrollService.getReleasesForWeek(_focusedDay);
+      
+      final Map<DateTime, List<AnimeRelease>> releasesByDay = {};
+      for (var release in releases) {
+        final date = DateTime(
+          release.releaseTime.year,
+          release.releaseTime.month,
+          release.releaseTime.day,
+        );
+        
+        if (releasesByDay[date] == null) {
+          releasesByDay[date] = [];
+        }
+        releasesByDay[date]!.add(release);
+      }
+
+      setState(() {
+        _releases = releasesByDay;
+        _isLoading = false;
+      });
+    } catch (e) {
+      print('Error loading releases: $e');
+      setState(() {
+        _isLoading = false;
+      });
+    }
+  }
+  
+  Future<void> _forceRefresh() async {
+    setState(() {
+      _isLoading = true;
+    });
+
+    try {
+      final releases = await _crunchyrollService.forceRefresh();
+      
+      final Map<DateTime, List<AnimeRelease>> releasesByDay = {};
+      for (var release in releases) {
+        final date = DateTime(
+          release.releaseTime.year,
+          release.releaseTime.month,
+          release.releaseTime.day,
+        );
+        
+        if (releasesByDay[date] == null) {
+          releasesByDay[date] = [];
+        }
+        releasesByDay[date]!.add(release);
+      }
+
+      setState(() {
+        _releases = releasesByDay;
+        _isLoading = false;
+      });
+    } catch (e) {
+      print('Error during force refresh: $e');
+      setState(() {
+        _isLoading = false;
+      });
+    }
+  }
+
+  void _showAnimeDetailsDialog(BuildContext context, AnimeRelease release) {
+    showDialog(
+      context: context,
+      builder: (BuildContext context) {
+        return _AnimeDetailsDialog(
+          release: release,
+          crunchyrollService: _crunchyrollService,
+        );
+      },
+    );
+  }
+
+  List<AnimeRelease> _getReleasesForDay(DateTime day) {
+    final date = DateTime(day.year, day.month, day.day);
+    return _releases[date] ?? [];
+  }
+
+  @override
+  Widget build(BuildContext context) {
+    return Scaffold(
+      appBar: AppBar(
+        backgroundColor: Theme.of(context).colorScheme.inversePrimary,
+        title: Column(
+          crossAxisAlignment: CrossAxisAlignment.start,
+          mainAxisSize: MainAxisSize.min,
+          children: [
+            const Text('Crunchyroll Anime Kalender'),
+            if (_isLoadingImages)
+              Text(
+                'Lade Bilder... $_imagesLoaded/$_imagesToLoad',
+                style: TextStyle(
+                  fontSize: 12,
+                  color: Theme.of(context).colorScheme.onPrimaryContainer.withOpacity(0.7),
+                ),
+              ),
+          ],
+        ),
+        elevation: 2,
+        bottom: _isLoadingImages
+            ? PreferredSize(
+                preferredSize: const Size.fromHeight(4),
+                child: LinearProgressIndicator(
+                  value: _imagesToLoad > 0 ? _imagesLoaded / _imagesToLoad : null,
+                  backgroundColor: Colors.transparent,
+                  valueColor: AlwaysStoppedAnimation<Color>(
+                    Theme.of(context).colorScheme.primary,
+                  ),
+                ),
+              )
+            : null,
+      ),
+      body: RefreshIndicator(
+        onRefresh: _forceRefresh,
+        child: Column(
+          children: [
+            TableCalendar<AnimeRelease>(
+            locale: 'de_DE',
+            firstDay: DateTime.utc(2020, 1, 1),
+            lastDay: DateTime.utc(2030, 12, 31),
+            focusedDay: _focusedDay,
+            calendarFormat: _calendarFormat,
+            startingDayOfWeek: StartingDayOfWeek.monday,
+            selectedDayPredicate: (day) {
+              return isSameDay(_selectedDay, day);
+            },
+            onDaySelected: (selectedDay, focusedDay) {
+              if (!isSameDay(_selectedDay, selectedDay)) {
+                setState(() {
+                  _selectedDay = selectedDay;
+                  _focusedDay = focusedDay;
+                });
+              }
+            },
+            onFormatChanged: (format) {
+              if (_calendarFormat != format) {
+                setState(() {
+                  _calendarFormat = format;
+                });
+                _saveCalendarFormat(format);
+              }
+            },
+            onPageChanged: (focusedDay) {
+              _focusedDay = focusedDay;
+              _loadReleases();
+            },
+            eventLoader: _getReleasesForDay,
+            calendarStyle: CalendarStyle(
+              todayDecoration: BoxDecoration(
+                color: Colors.orange.withOpacity(0.5),
+                shape: BoxShape.circle,
+              ),
+              selectedDecoration: const BoxDecoration(
+                color: Colors.orange,
+                shape: BoxShape.circle,
+              ),
