+              _releases[date]!.add(release);
+            }
+          }
+          
+          // Verarbeite Releases aus Nächstmonat
+          for (var release in nextMonthReleases) {
+            final date = DateTime(
+              release.releaseTime.year,
+              release.releaseTime.month,
+              release.releaseTime.day,
