+              release.releaseTime.month,
+              release.releaseTime.day,
+            );
+            
+            if (!_releases.containsKey(date)) {
+              _releases[date] = [];
+            }
+            
+            // Füge hinzu wenn nicht bereits vorhanden (Duplikat-Prüfung)
