+              _releases[date]!.add(release);
+            }
+          }
+        }
+      }
+      
+      // Trigger UI Update um Punkte anzuzeigen
+      if (mounted) {
+        setState(() {});
+      }
+      
+      if (kDebugMode) print('✓ Loaded ${_releases.length} days with anime releases from cache');
+    } catch (e) {
+      if (kDebugMode) print('Error loading cached months: $e');
+    }
+  }
