+  @override
+  void initState() {
+    super.initState();
+    _favoritesRepository = FavoritesRepository();
+    _checkIfFavorite();
+    
+    // Höre auf globale Favoriten-Änderungen
+    favoritesChangeNotifier.addListener(_onFavoritesChanged);
+  }
+
+  @override
+  void dispose() {
+    favoritesChangeNotifier.removeListener(_onFavoritesChanged);
+    super.dispose();
