+              )
+            : null,
+      ),
+      body: RefreshIndicator(
+        onRefresh: _forceRefresh,
+        child: Column(
+          children: [
+            TableCalendar<AnimeRelease>(
+              locale: 'de_DE',
+              firstDay: DateTime.utc(2020, 1, 1),
+              lastDay: DateTime.utc(2030, 12, 31),
+              focusedDay: _focusedDay,
+              calendarFormat: _calendarFormat,
+              startingDayOfWeek: StartingDayOfWeek.monday,
+              selectedDayPredicate: (day) {
+                return isSameDay(_selectedDay, day);
+              },
+              onDaySelected: (selectedDay, focusedDay) {
+                if (!isSameDay(_selectedDay, selectedDay)) {
+                  setState(() {
+                    _selectedDay = selectedDay;
+                    _focusedDay = focusedDay;
+                  });
+                  // Lade Releases für den neuen ausgewählten Tag
+                  _loadReleases();
+                }
+              },
+              onFormatChanged: (format) {
+                if (_calendarFormat != format) {
+                  setState(() {
+                    _calendarFormat = format;
+                  });
+                  _saveCalendarFormat(format);
+                }
+              },
+              onPageChanged: (focusedDay) {
+                // Update focused day and ensure in two-week format
+                // the current week is shown in the bottom row when possible.
+                _focusedDay = focusedDay;
+                if (_calendarFormat == CalendarFormat.twoWeeks) {
+                  // Helper: start of week (Monday)
+                  DateTime startOfWeek(DateTime d) {
+                    return DateTime(d.year, d.month, d.day)
+                        .subtract(Duration(days: d.weekday - 1));
+                  }
+
+                  final pageStart = startOfWeek(_focusedDay);
+                  final currentStart = startOfWeek(DateTime.now());
+
+                  // If the current week would be the top row on this two-week page,
+                  // shift the focused day forward by 7 days so the current week
+                  // appears in the bottom row instead.
+                  if (currentStart == pageStart) {
+                    // Move page forward one week
+                    _focusedDay = _focusedDay.add(const Duration(days: 7));
+                  }
+                }
+
+                _loadReleases();
+              },
+              eventLoader: _getReleasesForDay,
+              calendarStyle: CalendarStyle(
+                todayDecoration: BoxDecoration(
+                  color: Theme.of(context).colorScheme.primary.withOpacity(0.5),
