+  /// Returns a focusedDay so that in two-week view, the current week is always in the second row.
+  DateTime _adjustFocusedDayForTwoWeekView(DateTime focusedDay) {
+    // Start of week (Monday)
+    DateTime startOfWeek(DateTime d) => d.subtract(Duration(days: d.weekday - 1));
+    final now = DateTime.now();
+    final currentWeekStart = startOfWeek(now);
+    final pageStart = startOfWeek(focusedDay);
+    // If the current week is not in the second row, shift the page so it is
+    if (pageStart.add(const Duration(days: 7)) == currentWeekStart) {
+      // Already correct: current week is in second row
+      return focusedDay;
+    } else {
+      // Shift so that the two-week window ends with the current week
+      return currentWeekStart;
+    }
+  }
+  DateTime? _selectedDay;
+  Map<DateTime, List<AnimeRelease>> _releases = {};
+  final CrunchyrollService _crunchyrollService = CrunchyrollService();
