+  /// Returns a focusedDay so that in two-week view, the current week is always in the second row.
+  DateTime _adjustFocusedDayForTwoWeekView(DateTime focusedDay) {
+    // Start of week (Monday)
+    DateTime startOfWeek(DateTime d) => d.subtract(Duration(days: d.weekday - 1));
+    final now = DateTime.now();
+    final currentWeekStart = startOfWeek(now);
+    // For current week to be in the second (bottom) row of a two-week view,
+    // the focused day must be in the previous week.
+    // This way the calendar shows: [previous week, current week]
+    final previousWeekStart = currentWeekStart.subtract(const Duration(days: 7));
