+  /// Returns a focusedDay so that in two-week view, the current week is always in the second row.
+  DateTime _adjustFocusedDayForTwoWeekView(DateTime focusedDay) {
+    // Normalize to date-only then compute start of week (Monday)
+    DateTime startOfWeek(DateTime d) {
+      final dateOnly = DateTime(d.year, d.month, d.day);
+      return dateOnly.subtract(Duration(days: dateOnly.weekday - 1));
+    }
+
+    final now = DateTime.now();
+    final currentWeekStart = startOfWeek(now);
+    final pageStart = startOfWeek(focusedDay);
+
+    final previousWeekStart = currentWeekStart.subtract(const Duration(days: 7));
+
+    if (kDebugMode) {
+      print('twoWeekAdjust: focusedDay=$focusedDay, pageStart=$pageStart, currentWeekStart=$currentWeekStart');
+    }
+
+    // If the page start equals the current week start, that means the current
+    // week would be shown in the first (top) row — so shift to previous week
+    // so current week appears in the second (bottom) row. Otherwise leave as-is.
+    if (pageStart == currentWeekStart) {
+      if (kDebugMode) print('twoWeekAdjust: shifting to previousWeekStart=$previousWeekStart');
+      return previousWeekStart;
+    }
+
+    return focusedDay;
+  }
