-    if (kDebugMode) print('🧊 Freeze check: monthStart=${monthStart.month}/${monthStart.year}, twoMonthsAgo=${twoMonthsAgo.month}/${twoMonthsAgo.year}, isBefore=${monthStart.isBefore(twoMonthsAgo)}');
