+
+  Future<void> _checkIfFavorite() async {
+    try {
+      final isFav = await _favoritesRepository.isFavorite(widget.release.title);
+      if (mounted) {
+        setState(() {
+          _isFavorite = isFav;
+          _isLoadingFavorite = false;
