+  bool _isLoadingFavorite = true; // Loading State für Favoriten
+  final _translator = GoogleTranslator();
+  late final FavoritesRepository _favoritesRepository;
+
+  @override
+  void initState() {
+    super.initState();
+    _favoritesRepository = FavoritesRepository();
