+  Widget _buildReleaseList() {
+    final releases = _getReleasesForDay(_selectedDay ?? _focusedDay);
+
+    if (releases.isEmpty) {
+      return ListView(
+        physics: const AlwaysScrollableScrollPhysics(),
+        children: [
+          SizedBox(
