+
+  Future<void> _toggleFavorite() async {
+    try {
+      if (_isFavorite) {
+        // Aus Favoriten entfernen
+        await _favoritesRepository.removeFavorite(widget.release.title);
+        if (mounted) {
+          setState(() => _isFavorite = false);
+          ScaffoldMessenger.of(context).showSnackBar(
