+                            child: Center(
+                              child: Builder(builder: (context) {
+                                final selected = _selectedDay ?? _focusedDay;
+                                final dayNumber = DateFormat('d').format(selected);
+                                return GestureDetector(
+                                  onTap: () => _showSelectedDateDialog(selected),
+                                  child: CircleAvatar(
