+  Widget _buildReleaseList() {
+    final releases = _getReleasesForDay(_selectedDay ?? _focusedDay);
+
+    Widget content;
+
+    if (_isLoadingReleases) {
+      content = ListView(
+        physics: const AlwaysScrollableScrollPhysics(),
+        children: [
+          SizedBox(
+            height: 200,
+            child: Center(
+              child: Column(
+                mainAxisAlignment: MainAxisAlignment.center,
+                children: const [
+                  CircularProgressIndicator(),
+                  SizedBox(height: 16),
+                  Text(
+                    'Lade Releases…',
+                    style: TextStyle(fontSize: 16, color: Colors.grey),
+                  ),
+                ],
+              ),
+            ),
+          ),
+        ],
+      );
+    } else if (releases.isEmpty) {
+      content = ListView(
+        physics: const AlwaysScrollableScrollPhysics(),
+        children: [
+          SizedBox(
+            height: 200,
+            child: Center(
+              child: Column(
+                mainAxisAlignment: MainAxisAlignment.center,
+                children: [
+                  Icon(Icons.event_busy, size: 64, color: Colors.grey[400]),
+                  const SizedBox(height: 16),
+                  const Text(
+                    'Keine Anime-Releases an diesem Tag bisher.',
+                    style: TextStyle(fontSize: 16, color: Colors.grey),
+                  ),
+                ],
+              ),
+            ),
+          ),
+        ],
+      );
+    } else {
+      content = ListView.builder(
+        physics: const AlwaysScrollableScrollPhysics(),
+        padding: const EdgeInsets.all(8),
+        itemCount: releases.length,
+        itemBuilder: (context, index) {
+          final release = releases[index];
+          return _buildReleaseCard(release);
+        },
+      );
+    }
+
+    // Wrap the content in a GestureDetector so horizontal swipes change the day.
+    // Keep HitTestBehavior.opaque so empty areas still receive gestures.
+    return GestureDetector(
+      behavior: HitTestBehavior.opaque,
+      onHorizontalDragEnd: (details) {
+        final velocity = details.primaryVelocity ?? 0.0;
+        // Swipe left (negative velocity) -> next day
+        if (velocity < -200) {
+          setState(() {
+            final base = _selectedDay ?? _focusedDay;
+            _selectedDay = DateTime(base.year, base.month, base.day).add(const Duration(days: 1));
+            _focusedDay = _selectedDay!;
+          });
+          _loadReleases();
+        }
+        // Swipe right (positive velocity) -> previous day
+        else if (velocity > 200) {
+          setState(() {
+            final base = _selectedDay ?? _focusedDay;
+            _selectedDay = DateTime(base.year, base.month, base.day).subtract(const Duration(days: 1));
+            _focusedDay = _selectedDay!;
+          });
+          _loadReleases();
+        }
+      },
+      child: content,
+    );
+  }
