-      final endX = size.width * ((i + 2) / 8);
-      final endY = size.height;
-
-      canvas.drawLine(Offset(startX, startY), Offset(endX, endY), paint);
-    }
-
-    // Zeichne einige Kreise (wie Anime-Highlights)
-    paint.style = PaintingStyle.fill;
