+class _ReleaseCardState extends State<_ReleaseCard> {
+  bool _isFavorite = false;
+  late final FavoritesRepository _favoritesRepository;
+
+  @override
+  void initState() {
+    super.initState();
+    _favoritesRepository = FavoritesRepository();
+    _checkIfFavorite();
