+                                return GestureDetector(
+                                  onTap: () => _showSelectedDateDialog(selected),
+                                  child: CircleAvatar(
+                                    radius: 18,
+                                    backgroundColor: Theme.of(context).colorScheme.primary,
+                                    child: Text(
